bool is_polygon_convex(const std::vector<Point_2>& polygon) {
    // Handle edge cases: less than 3 points is convex
    if (polygon.size() < 3) {
        return true;
    }

    // Get orientation of first three points
    auto orientation = CGAL::orientation(polygon[0], polygon[1], polygon[2]);

    // Check all consecutive triplets
    for (size_t i = 1; i < polygon.size(); ++i) {
        size_t j = (i + 1) % polygon.size();
        size_t k = (i + 2) % polygon.size();

        auto current_orientation = CGAL::orientation(polygon[i], polygon[j], polygon[k]);

        // If orientation changes, polygon is not convex
        if (current_orientation != orientation) {
            return false;
        }
    }

    return true;
}

